rtext_empty=_=>{const r=lmt();tab_set(r,'text',[]),tab_set(r,'font',[]),tab_set(r,'arg',[]),tab_set(r,'pat',[]);return r}
rtext_len=tab=>tab_get(tab,'text').reduce((x,y)=>x+ls(y).length,0)
